    private MaterializedResult executePipelinePlan(PipelinePlan plan, List<Type> outputTypes)
    {
        List<Page> outputPages = executePipelinePlan(plan);
        MaterializedResult.Builder result = MaterializedResult.resultBuilder(taskContext().getSession(), outputTypes);
        for (Page page : outputPages) {
            result.page(page);
        }
        return result.build();
    }

    private List<Page> executePipelinePlan(PipelinePlan plan)
    {
        List<Page> outputPages = new ArrayList<>();
        io.trino.operator.TaskContext taskContext = taskContext();
        DriverContext driverContext = newDriverContext(taskContext);
        PipelineOperators pipeline = createPipelineOperators(taskContext, driverContext, plan, outputPages::add);

        try (Driver driver = Driver.createDriver(driverContext, pipeline.mainOperators())) {
            processDriver(driver);
        }
        catch (Exception exception) {
            throw new RuntimeException("Unable to execute Trino TPC-DS parquet pipeline plan", exception);
        }

        // RIGHT/FULL lookup joins emit unmatched build rows from a separate source driver.
        // This mirrors LocalExecutionPlanner.addLookupOuterDrivers: the outer source is
        // followed by duplicates of every operator downstream of the join.
        for (DriverOperators outerDriver : pipeline.outerDrivers()) {
            try (Driver driver = Driver.createDriver(outerDriver.driverContext(), outerDriver.operators())) {
                processDriver(driver);
            }
            catch (Exception exception) {
                throw new RuntimeException("Unable to execute Trino lookup-outer driver", exception);
            }
        }

        return outputPages;
    }

    private List<Page> executeSqlAggregationStage(
            List<Page> inputPages,
            List<Type> inputTypes,
            int partitionCount,
            int[] hashChannels,
            Supplier<List<PipelineStep>> steps,
            List<Type> outputTypes,
            String profileName)
    {
        List<List<Page>> partitions = partitionPages(inputPages, inputTypes, partitionCount, hashChannels);
        List<Page> output = new ArrayList<>();
        for (int partition = 0; partition < partitionCount; partition++) {
            output.addAll(executePipelinePlan(new PipelinePlan(
                    new PagesPipelineSource(partitions.get(partition), profileName + ".source"),
                    steps.get(),
                    profileName + ".sink",
                    outputTypes)));
        }
        return output;
    }

    private static List<List<Page>> partitionPages(List<Page> pages, List<Type> inputTypes, int partitionCount, int[] hashChannels)
    {
        List<List<Page>> partitions = new ArrayList<>(partitionCount);
        for (int partition = 0; partition < partitionCount; partition++) {
            partitions.add(new ArrayList<>());
        }
        if (hashChannels.length == 0) {
            for (int page = 0; page < pages.size(); page++) {
                Page input = pages.get(page);
                int[] positions = new int[input.getPositionCount()];
                Arrays.setAll(positions, index -> index);
                partitions.get(page % partitionCount).add(input.copyPositions(positions, 0, positions.length));
            }
            return partitions;
        }

        List<Type> hashTypes = Arrays.stream(hashChannels)
                .mapToObj(inputTypes::get)
                .toList();
        InterpretedHashGenerator hashGenerator = InterpretedHashGenerator.createChannelsHashGenerator(
                hashTypes,
                hashChannels,
                new TypeOperators());
        for (Page page : pages) {
            int positionCount = page.getPositionCount();
            long[] hashes = new long[positionCount];
            for (int position = 0; position < positionCount; position++) {
                hashes[position] = hashGenerator.hashPosition(position, page);
            }
            int[][] positions = new int[partitionCount][positionCount];
            int[] counts = new int[partitionCount];
            for (int position = 0; position < positionCount; position++) {
                int partition = Math.floorMod(hashes[position], partitionCount);
                positions[partition][counts[partition]++] = position;
            }
            for (int partition = 0; partition < partitionCount; partition++) {
                if (counts[partition] > 0) {
                    partitions.get(partition).add(page.copyPositions(positions[partition], 0, counts[partition]));
                }
            }
        }
        return partitions;
    }

    private io.trino.operator.TaskContext taskContext()
    {
        return TestingTaskContext.builder(executor, scheduledExecutor, TestingSession.testSessionBuilder().build())
                .setQueryMaxMemory(DataSize.of(12, GIGABYTE))
                .setMemoryPoolSize(DataSize.of(12, GIGABYTE))
                .build();
    }

    private void processDriver(Driver driver)
            throws Exception
    {
        while (!driver.isFinished()) {
            ListenableFuture<Void> blocked = driver.processUntilBlocked();
            if (!blocked.isDone()) {
                waitForBlocked(blocked);
            }
        }
    }

    private DriverContext newDriverContext(io.trino.operator.TaskContext taskContext)
    {
        return taskContext.addPipelineContext(nextDynamicPipelineId.getAndIncrement(), true, true, false).addDriverContext();
    }

    private List<Operator> createOperators(io.trino.operator.TaskContext taskContext, DriverContext driverContext, PipelinePlan plan, java.util.function.Consumer<Page> pageConsumer)
    {
        PipelineOperators pipeline = createPipelineOperators(taskContext, driverContext, plan, pageConsumer);
        if (!pipeline.outerDrivers().isEmpty()) {
            throw new IllegalArgumentException("Lookup-outer joins are only supported in a directly executed pipeline plan");
        }
        return pipeline.mainOperators();
    }

    private PipelineOperators createPipelineOperators(io.trino.operator.TaskContext taskContext, DriverContext driverContext, PipelinePlan plan, java.util.function.Consumer<Page> pageConsumer)
    {
        List<Operator> operators = new ArrayList<>();
        List<PendingOuterDriver> pendingOuterDrivers = new ArrayList<>();
        operators.add(createSourceOperator(taskContext, driverContext, plan.source()));

        for (PipelineStep step : plan.steps()) {
            OperatorFactory factory = step.createOperatorFactory(taskContext, this);

            // An outer driver created by an earlier join must run through the same
            // downstream operator graph as the main probe driver.
            for (PendingOuterDriver outerDriver : pendingOuterDrivers) {
                OperatorFactory duplicate = factory.duplicate();
                outerDriver.operators().add(profiled(step.profileName(), duplicate.createOperator(outerDriver.driverContext())));
                duplicate.noMoreOperators();
            }

            if (factory instanceof JoinOperatorFactory joinFactory) {
                joinFactory.createOuterOperatorFactory().ifPresent(outerFactory -> {
                    DriverContext outerDriverContext = newDriverContext(taskContext);
                    List<Operator> outerOperators = new ArrayList<>();
                    outerOperators.add(profiled(step.profileName() + ".outer", outerFactory.createOperator(outerDriverContext)));
                    outerFactory.noMoreOperators();
                    pendingOuterDrivers.add(new PendingOuterDriver(outerDriverContext, outerOperators));
                });
            }

            operators.add(profiled(step.profileName(), factory.createOperator(driverContext)));
            factory.noMoreOperators();
        }

        operators.add(profiled(plan.sinkName(), new PageConsumerOperator(
                driverContext.addOperatorContext(1000, new PlanNodeId("sink"), PageConsumerOperator.class.getSimpleName()),
                pageConsumer,
                java.util.function.Function.identity())));
        for (PendingOuterDriver outerDriver : pendingOuterDrivers) {
            outerDriver.operators().add(profiled(plan.sinkName(), new PageConsumerOperator(
                    outerDriver.driverContext().addOperatorContext(1000, new PlanNodeId("sink"), PageConsumerOperator.class.getSimpleName()),
                    pageConsumer,
                    java.util.function.Function.identity())));
        }
        return new PipelineOperators(
                List.copyOf(operators),
                pendingOuterDrivers.stream()
                        .map(outer -> new DriverOperators(outer.driverContext(), List.copyOf(outer.operators())))
                        .toList());
    }

    private Operator createSourceOperator(io.trino.operator.TaskContext taskContext, DriverContext driverContext, PipelineSource source)
    {
        if (source instanceof FilesPipelineSource filesSource) {
            return profiled(
                    filesSource.profileName(),
                    new ParquetPageSourceOperator(
                            driverContext.addOperatorContext(0, new PlanNodeId("parquet-source-" + Math.abs(filesSource.profileName().hashCode())), ParquetPageSourceOperator.class.getSimpleName()),
                            filesSource.files(),
                            filesSource.columns()));
        }
        if (source instanceof PagesPipelineSource pagesSource) {
            return profiled(
                    pagesSource.profileName(),
                    new PagesSourceOperator(
                            driverContext.addOperatorContext(0, new PlanNodeId("pages-source-" + Math.abs(pagesSource.profileName().hashCode())), PagesSourceOperator.class.getSimpleName()),
                            pagesSource.pages()));
        }
        if (source instanceof UnionPipelineSource unionSource) {
            return profiled(
                    unionSource.profileName(),
                    new UnionPipelineSourceOperator(
                            taskContext,
                            driverContext.addOperatorContext(0, new PlanNodeId("union-source-" + Math.abs(unionSource.profileName().hashCode())), UnionPipelineSourceOperator.class.getSimpleName()),
                            unionSource.plans()));
        }
        throw new IllegalArgumentException("Unsupported pipeline source: " + source);
    }

    private PipelinePlan relationPlan(TpcdsParquetTables tables, String tableName, List<String> columns, Optional<RowExpression> filter, List<RowExpression> projections, List<Type> outputTypes, String operatorName, String sinkName)
    {
        int operatorId = nextDynamicOperatorId.getAndIncrement();
        return new PipelinePlan(
                new FilesPipelineSource(tables.tableFiles(tableName), columns, operatorName + ".source"),
                List.of(namedFactoryStep(operatorName, filterAndProjectFactory(operatorId, filter, projections, outputTypes))),
                sinkName,
                outputTypes);
    }

