    private static PipelinePlan appendPlan(PipelinePlan plan, List<PipelineStep> additionalSteps, String sinkName)
    {
        return appendPlan(plan, additionalSteps, sinkName, plan.outputTypes());
    }

    private static PipelinePlan appendPlan(PipelinePlan plan, List<PipelineStep> additionalSteps, String sinkName, List<Type> outputTypes)
    {
        List<PipelineStep> steps = new ArrayList<>(plan.steps().size() + additionalSteps.size());
        steps.addAll(plan.steps());
        steps.addAll(additionalSteps);
        return new PipelinePlan(plan.source(), List.copyOf(steps), sinkName, outputTypes);
    }

    private PipelinePlan markDistinctPlan(PipelinePlan plan, List<Type> sourceTypes, List<Integer> distinctChannels, int operatorId, String queryName)
    {
        return appendPlan(
                plan,
                List.of(
                        namedMarkDistinctStep(queryName + ".mark_distinct", new MarkDistinctSpec(operatorId, sourceTypes, distinctChannels)),
                        namedFactoryStep(queryName + ".filter_distinct", filterAndProjectFactory(
                                operatorId + 1,
                                Optional.of(field(sourceTypes.size(), BOOLEAN)),
                                allFields(sourceTypes),
                                sourceTypes))),
                queryName + ".sink.distinct",
                sourceTypes);
    }

    private static List<Type> concatTypes(List<Type> left, List<Type> right)
    {
        List<Type> types = new ArrayList<>(left.size() + right.size());
        types.addAll(left);
        types.addAll(right);
        return types;
    }

    private static List<Type> selectedTypes(List<Type> types, List<Integer> channels)
    {
        return channels.stream()
                .map(types::get)
                .toList();
    }

    private static List<Type> joinOutputTypes(List<Type> probeTypes, List<Integer> probeChannels, List<Type> buildTypes, List<Integer> buildChannels)
    {
        return concatTypes(selectedTypes(probeTypes, probeChannels), selectedTypes(buildTypes, buildChannels));
    }

    private static List<RowExpression> identityProjections(List<Type> types)
    {
        List<RowExpression> projections = new ArrayList<>(types.size());
        for (int index = 0; index < types.size(); index++) {
            projections.add(field(index, types.get(index)));
        }
        return projections;
    }

    private static List<RowExpression> selectedProjections(List<Type> types, int... channels)
    {
        List<RowExpression> projections = new ArrayList<>(channels.length);
        for (int channel : channels) {
            projections.add(field(channel, types.get(channel)));
        }
        return projections;
    }

    private static WindowFunctionDefinition aggregateWindowFunction(String functionName, List<Type> argumentTypes, Type outputType, FrameInfo frameInfo, int... inputChannels)
    {
        ResolvedFunction resolvedFunction = FUNCTION_RESOLUTION.resolveFunction(functionName, fromTypes(argumentTypes));
        AggregationWindowFunctionSupplier supplier = new AggregationWindowFunctionSupplier(
                resolvedFunction.signature(),
                FUNCTION_RESOLUTION.getPlannerContext().getFunctionManager().getAggregationImplementation(resolvedFunction),
                resolvedFunction.functionNullability());
        return window(
                supplier,
                outputType,
                frameInfo,
                false,
                List.of(),
                java.util.Arrays.stream(inputChannels)
                        .boxed()
                        .toList());
    }

