    private record PipelineOperators(List<Operator> mainOperators, List<DriverOperators> outerDrivers) {}

    private record DriverOperators(DriverContext driverContext, List<Operator> operators) {}

    private record PendingOuterDriver(DriverContext driverContext, List<Operator> operators) {}

    private static final class PagesSourceOperator
            implements Operator
    {
        private final OperatorContext operatorContext;
        private final List<Page> pages;
        private int pageIndex;
        private boolean finished;

        private PagesSourceOperator(OperatorContext operatorContext, List<Page> pages)
        {
            this.operatorContext = operatorContext;
            this.pages = List.copyOf(pages);
        }

        @Override
        public OperatorContext getOperatorContext()
        {
            return operatorContext;
        }

        @Override
        public void finish()
        {
            finished = true;
        }

        @Override
        public boolean isFinished()
        {
            return finished || pageIndex == pages.size();
        }

        @Override
        public boolean needsInput()
        {
            return false;
        }

        @Override
        public void addInput(Page page)
        {
            throw new UnsupportedOperationException();
        }

        @Override
        public Page getOutput()
        {
            if (isFinished()) {
                return null;
            }
            Page page = pages.get(pageIndex++);
            operatorContext.recordProcessedInput(page.getSizeInBytes(), page.getPositionCount());
            return page;
        }
    }

    private static final class ParquetPageSourceOperator
            implements Operator
    {
        private final OperatorContext operatorContext;
        private final TrinoClickBenchPageReader reader;
        private boolean finished;

        private ParquetPageSourceOperator(OperatorContext operatorContext, List<Path> files, List<String> columns)
        {
            this.operatorContext = operatorContext;
            this.reader = new TrinoClickBenchPageReader(files, columns);
        }

        @Override
        public OperatorContext getOperatorContext()
        {
            return operatorContext;
        }

        @Override
        public void finish()
        {
            finished = true;
        }

        @Override
        public boolean isFinished()
        {
            return finished || !reader.hasNext();
        }

        @Override
        public boolean needsInput()
        {
            return false;
        }

        @Override
        public void addInput(Page page)
        {
            throw new UnsupportedOperationException();
        }

        @Override
        public Page getOutput()
        {
            if (finished || !reader.hasNext()) {
                return null;
            }
            Page page = reader.nextPage();
            operatorContext.recordProcessedInput(page.getSizeInBytes(), page.getPositionCount());
            return page;
        }

        @Override
        public void close()
        {
            reader.close();
        }
    }

    private final class UnionPipelineSourceOperator
            implements Operator
    {
        private final io.trino.operator.TaskContext taskContext;
        private final OperatorContext operatorContext;
        private final List<PipelinePlan> plans;
        private final Deque<Page> outputBuffer = new ArrayDeque<>();
        private final Deque<Driver> pendingDrivers = new ArrayDeque<>();

        private int currentPlanIndex;
        private Driver currentDriver;
        private String currentPlanName;
        private boolean finished;

        private UnionPipelineSourceOperator(io.trino.operator.TaskContext taskContext, OperatorContext operatorContext, List<PipelinePlan> plans)
        {
            this.taskContext = taskContext;
            this.operatorContext = operatorContext;
            this.plans = plans;
        }

        @Override
        public OperatorContext getOperatorContext()
        {
            return operatorContext;
        }

        @Override
        public void finish()
        {
            finished = true;
            closeAllDrivers();
        }

        @Override
        public boolean isFinished()
        {
            return finished;
        }

        @Override
        public boolean needsInput()
        {
            return false;
        }

        @Override
        public void addInput(Page page)
        {
            throw new UnsupportedOperationException();
        }

        @Override
        public Page getOutput()
        {
            if (finished) {
                return null;
            }

            while (outputBuffer.isEmpty()) {
                if (currentDriver == null) {
                    if (pendingDrivers.isEmpty()) {
                        if (currentPlanIndex >= plans.size()) {
                            finished = true;
                            return null;
                        }
                        PipelinePlan currentPlan = plans.get(currentPlanIndex++);
                        currentPlanName = currentPlan.sinkName();
                        createDriversForPlan(currentPlan);
                    }
                    currentDriver = pendingDrivers.removeFirst();
                }

                if (currentDriver.isFinished()) {
                    closeCurrentDriver();
                    continue;
                }

                try {
                    ListenableFuture<Void> blocked = currentDriver.processUntilBlocked();
                    if (outputBuffer.isEmpty() && !currentDriver.isFinished() && !blocked.isDone()) {
                        waitForBlocked(blocked);
                    }
                }
                catch (Exception exception) {
                    throw new RuntimeException("Unable to execute Trino union pipeline source for plan " + currentPlanName, exception);
                }

                if (currentDriver != null && currentDriver.isFinished()) {
                    closeCurrentDriver();
                }
            }

            Page page = outputBuffer.removeFirst();
            operatorContext.recordProcessedInput(page.getSizeInBytes(), page.getPositionCount());
            return page;
        }

        @Override
        public void close()
        {
            finished = true;
            closeAllDrivers();
        }

        private void createDriversForPlan(PipelinePlan plan)
        {
            DriverContext childDriverContext = newDriverContext(taskContext);
            PipelineOperators pipeline = createPipelineOperators(taskContext, childDriverContext, plan, outputBuffer::add);
            pendingDrivers.addLast(Driver.createDriver(childDriverContext, pipeline.mainOperators()));
            for (DriverOperators outerDriver : pipeline.outerDrivers()) {
                pendingDrivers.addLast(Driver.createDriver(outerDriver.driverContext(), outerDriver.operators()));
            }
        }

        private void closeCurrentDriver()
        {
            if (currentDriver != null) {
                currentDriver.close();
                currentDriver = null;
                if (pendingDrivers.isEmpty()) {
                    currentPlanName = null;
                }
            }
        }

        private void closeAllDrivers()
        {
            closeCurrentDriver();
            while (!pendingDrivers.isEmpty()) {
                pendingDrivers.removeFirst().close();
            }
            currentPlanName = null;
        }
    }

    private Operator profiled(String name, Operator operator)
    {
        TrinoOperatorCpuProfile profile = CURRENT_OPERATOR_CPU_PROFILE.get();
        if (profile == null || name == null) {
            return operator;
        }
        return profile.wrap(name, operator);
    }

